on conflict (id) do update set initials = excluded.initials, name = excluded.name, qualification = excluded.qualification, focus = excluded.focus, image_url = excluded.image_url, "order" = excluded."order", is_active = excluded.is_active, created_at = excluded.created_at, updated_at = excluded.updated_at;

