on conflict (id) do update set slug = excluded.slug, title = excluded.title, category = excluded.category, duration = excluded.duration, format = excluded.format, owner = excluded.owner, audience = excluded.audience, summary = excluded.summary, focus = excluded.focus, detail = excluded.detail, icon = excluded.icon, image_url = excluded.image_url, "order" = excluded."order", is_active = excluded.is_active, created_at = excluded.created_at, updated_at = excluded.updated_at;

select setval(pg_get_serial_sequence('public.ipc_images', 'id'), coalesce((select max(id) from public.ipc_images), 1), true);
select setval(pg_get_serial_sequence('public.partners', 'id'), coalesce((select max(id) from public.partners), 1), true);
